using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace CodexProxyDesktop {
 sealed partial class MainWindow {
  readonly Label recordSummary=Theme.Label("");readonly DataGridView recordGrid=new DataGridView();readonly DateTimePicker recordFrom=new DateTimePicker(),recordTo=new DateTimePicker();
  readonly CheckBox recordEnabled=new CheckBox();readonly NumericUpDown recordDays=new NumericUpDown(),recordCapacity=new NumericUpDown();DateTime recordRefresh=DateTime.MinValue;
  void BuildDiagnostics(){var page=Page("使用记录");var grid=GridLayout(90,50,48,50,-1,64);page.Controls.Add(grid);recordSummary.Dock=DockStyle.Fill;recordSummary.ForeColor=Theme.Muted;recordSummary.Padding=new Padding(4,6,0,0);grid.Controls.Add(recordSummary,0,0);
   var options=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};recordEnabled.Text="启用本地记录";recordEnabled.Width=130;recordEnabled.ForeColor=Theme.Text;recordEnabled.Checked=engine.Config().DiagnosticsEnabled;options.Controls.Add(recordEnabled);var days=Theme.Label("最多保留天数");days.Width=100;days.Height=30;options.Controls.Add(days);foreach(var box in new[]{recordDays,recordCapacity}){box.Width=72;box.BackColor=Theme.Card;box.ForeColor=Theme.Text;}recordDays.Minimum=1;recordDays.Maximum=90;recordDays.Value=DiagnosticJournal.Days(engine.Config());options.Controls.Add(recordDays);var capacity=Theme.Label("容量上限 MB");capacity.Width=110;capacity.Height=30;options.Controls.Add(capacity);recordCapacity.Minimum=5;recordCapacity.Maximum=500;recordCapacity.Value=DiagnosticJournal.Megabytes(engine.Config());options.Controls.Add(recordCapacity);grid.Controls.Add(options,0,1);
   recordEnabled.CheckedChanged+=(s,a)=>{if(loading)return;if(!recordEnabled.Checked)monitor.Journal.Disable(DateTime.UtcNow);engine.Update(c=>c.DiagnosticsEnabled=recordEnabled.Checked);recordRefresh=DateTime.MinValue;};recordDays.ValueChanged+=(s,a)=>{if(!loading){engine.Update(c=>c.DiagnosticRetentionDays=(int)recordDays.Value);recordRefresh=DateTime.MinValue;}};recordCapacity.ValueChanged+=(s,a)=>{if(!loading){engine.Update(c=>c.DiagnosticMaxMb=(int)recordCapacity.Value);recordRefresh=DateTime.MinValue;}};
   var dates=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};var start=Theme.Label("开始日期");start.Width=80;start.Height=30;dates.Controls.Add(start);foreach(var picker in new[]{recordFrom,recordTo}){picker.Format=DateTimePickerFormat.Custom;picker.CustomFormat="yyyy-MM-dd";picker.Width=145;picker.Value=DateTime.Today;picker.ValueChanged+=(s,a)=>recordRefresh=DateTime.MinValue;}dates.Controls.Add(recordFrom);var end=Theme.Label("结束日期（含）");end.Width=120;end.Height=30;dates.Controls.Add(end);dates.Controls.Add(recordTo);grid.Controls.Add(dates,0,2);
   var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};var export=Theme.Button("导出诊断包",true);export.Click+=(s,a)=>ExportDiagnostics();var working=Theme.Button("标记仍能使用");working.Click+=(s,a)=>{monitor.ReportWorking();recordRefresh=DateTime.MinValue;Notice("已标记：提示异常但仍能使用，并关联前后五分钟现场。");};var stall=Theme.Button("报告任务卡住");stall.Click+=(s,a)=>{monitor.ReportStall();recordRefresh=DateTime.MinValue;Notice("已保存卡顿标记并请求复测；保留当前任务。");};var folder=Theme.Button("打开记录目录");folder.Click+=(s,a)=>{try{if(Directory.Exists(monitor.Journal.DirectoryPath))Process.Start("explorer.exe",monitor.Journal.DirectoryPath);else Notice("尚未生成本地记录，请开启记录后稍候。");}catch{Notice("暂时无法打开记录目录。");}};actions.Controls.AddRange(new Control[]{export,working,stall,folder});grid.Controls.Add(actions,0,3);
   recordGrid.Dock=DockStyle.Fill;recordGrid.ReadOnly=true;recordGrid.AllowUserToAddRows=recordGrid.AllowUserToDeleteRows=false;recordGrid.RowHeadersVisible=false;recordGrid.BackgroundColor=Theme.Card;recordGrid.BorderStyle=BorderStyle.None;recordGrid.GridColor=Theme.Border;recordGrid.EnableHeadersVisualStyles=false;recordGrid.ColumnHeadersDefaultCellStyle.BackColor=Theme.Background;recordGrid.ColumnHeadersDefaultCellStyle.ForeColor=Theme.Text;recordGrid.DefaultCellStyle.BackColor=Theme.Card;recordGrid.DefaultCellStyle.ForeColor=Theme.Text;recordGrid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(34,65,67);recordGrid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;recordGrid.RowTemplate.Height=30;recordGrid.ColumnHeadersHeight=34;string[] headers={"时间","事件","显示状态","节点","本次编号"};int[] widths={158,220,240,180,100};for(int i=0;i<headers.Length;i++)recordGrid.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=headers[i],Width=widths[i],SortMode=DataGridViewColumnSortMode.NotSortable});recordGrid.CellDoubleClick+=(s,a)=>{if(a.RowIndex>=0)ShowRecord((DiagnosticRow)recordGrid.Rows[a.RowIndex].Tag);};grid.Controls.Add(recordGrid,0,4);
   var help=Theme.Label("显示所选日期最近 200 条，双击查看判断依据；导出包含该范围内全部保留记录。\n正常每 5 秒采样，状态变化即时记录；异常后 5 分钟每秒采样。仅保存网络元数据。",9);help.Dock=DockStyle.Fill;help.ForeColor=Theme.Muted;help.Padding=new Padding(0,8,0,0);grid.Controls.Add(help,0,5);
  }
  void RefreshDiagnostics(){if(!pages.ContainsKey("使用记录")||!pages["使用记录"].Visible||DateTime.UtcNow<recordRefresh)return;recordRefresh=DateTime.UtcNow.AddSeconds(5);recordSummary.Text=monitor.Journal.Summary();try{DateTime from=recordFrom.Value.Date.ToUniversalTime(),to=recordTo.Value.Date.AddDays(1).ToUniversalTime();recordGrid.Rows.Clear();if(to<=from){recordSummary.Text+="\n请选择有效日期范围。";return;}foreach(var row in monitor.Journal.Read(from,to)){int index=recordGrid.Rows.Add(Presentation.When(row.Utc),row.Event,row.Status,row.Node,String.IsNullOrEmpty(row.Session)?"":row.Session.Substring(0,Math.Min(8,row.Session.Length)));recordGrid.Rows[index].Tag=row;}}catch{recordSummary.Text+="\n部分记录暂不可读，稍后自动重试。";}}
  async void ExportDiagnostics(){DateTime from=recordFrom.Value.Date.ToUniversalTime(),to=recordTo.Value.Date.AddDays(1).ToUniversalTime();if(to<=from){Notice("结束日期不能早于开始日期。");return;}using(var dialog=new SaveFileDialog{Title="导出本地诊断记录",Filter="诊断压缩包|*.zip",FileName="代理诊断_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".zip",OverwritePrompt=true}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;string temporary=dialog.FileName+"."+Guid.NewGuid().ToString("N")+".tmp";try{int count=await Task.Run(()=>monitor.Journal.Export(temporary,from,to));if(File.Exists(dialog.FileName))File.Replace(temporary,dialog.FileName,null);else File.Move(temporary,dialog.FileName);Notice("已导出 "+count+" 条记录；诊断包包含节点名称，不包含聊天和密钥。");}catch{if(File.Exists(temporary))try{File.Delete(temporary);}catch{}Notice("导出失败，请检查保存位置与文件是否被占用。");}}}
  void ShowRecord(DiagnosticRow row){var text=new StringBuilder();text.AppendLine("时间："+Presentation.When(row.Utc));text.AppendLine("运行编号："+row.Session);text.AppendLine("程序版本："+row.Version);text.AppendLine("事件："+row.Event);text.AppendLine("界面状态："+row.Status);text.AppendLine("判断依据："+row.Reason);text.AppendLine("当前节点："+row.Node+"；策略组："+row.Group);text.AppendLine("路线："+row.Route+"；数据年龄（秒）："+row.RouteAgeSeconds);text.AppendLine("路线未确认原因："+row.RuleIssue);text.AppendLine("自动恢复限制："+row.RecoveryBlock);text.AppendLine("匿名 HTTPS 响应时间："+Presentation.When(row.AnonymousResponseUtc));text.AppendLine("ChatGPT 探测："+row.ChatGpt);text.AppendLine("Codex 环境探测："+row.Codex);text.AppendLine("探测数据年龄（秒）："+row.ProbeAgeSeconds);text.AppendLine("最近应用下行："+Presentation.When(row.AppResponseUtc)+"；实际节点："+row.AppResponseNode);text.AppendLine("关联下行 / 上行（字节每秒）："+row.ServiceDown+" / "+row.ServiceUp);text.AppendLine("流量数据年龄（秒）："+row.TrafficAgeSeconds);text.AppendLine("故障事件编号："+row.IncidentId);text.AppendLine("自动处理阶段："+row.CasePhase);text.AppendLine("当前动作："+row.CaseAction);text.AppendLine("最初原因："+row.CaseInitialReason);text.AppendLine("处理结果："+row.CaseOutcome);text.AppendLine("事件开始 / 结束："+Presentation.When(row.CaseStartedUtc)+" / "+Presentation.When(row.CaseEndedUtc));text.AppendLine("恢复操作次数："+row.RecoveryAttempts);if(!String.IsNullOrEmpty(row.WindowStartUtc))text.AppendLine("现场范围："+Presentation.When(row.WindowStartUtc)+" 至 "+Presentation.When(row.WindowEndUtc));using(var dialog=new Form{Text="使用记录详情",Size=new Size(800,610),StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Background}){dialog.Controls.Add(new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,Text=text.ToString(),BackColor=Theme.Card,ForeColor=Theme.Text,Font=Theme.Font(10)});dialog.ShowDialog(this);}}
 }
}
